pub fn serialize_method_semantics(
    value: Option<Rc<MethodSemantics>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
    key_to_id: Rc<HashMap<String, String>>,
) -> String {
    match value.as_deref().cloned() {
        Some(MethodSemantics::PlainMethodSemantics) => {
            "{\"kind\": \"PlainMethodSemantics\"}".to_string()
        }
        Some(MethodSemantics::AlgebraMethodSemantics {
            method_def,
            fold_accumulator_type,
            ..
        }) => {
            let mn = authored_name_at(source_indices.clone(), method_def.clone());
            v1_rt::concat(
                v1_rt::concat(
                    v1_rt::concat(
                        v1_rt::concat(
                            "{\"kind\": \"AlgebraMethodSemantics\", \"method_name\": ".to_string(),
                            json_quote(mn),
                        ),
                        ", \"fold_accumulator_type\": ".to_string(),
                    ),
                    json_optional_node_ref(fold_accumulator_type.clone(), key_to_id.clone()),
                ),
                "}".to_string(),
            )
        }
        Some(MethodSemantics::ServiceMethodSemantics {
            service_name,
            op_params,
            ..
        }) => v1_rt::concat(
            v1_rt::concat(
                v1_rt::concat(
                    v1_rt::concat(
                        "{\"kind\": \"ServiceMethodSemantics\", \"service_name\": ".to_string(),
                        json_quote(service_name.clone()),
                    ),
                    ", \"op_params\": ".to_string(),
                ),
                json_list(Rc::new({
                    let mut __result = Vec::new();
                    for p in op_params.clone().iter().cloned() {
                        __result.push(serialize_param(
                            p.clone(),
                            source_indices.clone(),
                            key_to_id.clone(),
                        ));
                    }
                    __result
                })),
            ),
            "}".to_string(),
        ),
        None => "null".to_string(),
    }
}

