pub fn is_import_statement_node(n: Rc<Node>) -> bool {
    (import_is_all(n.clone())
        || (((((n.children.clone().len() as i64) > 0) && (n.body.clone() == None))
            && (n.expr_data.clone() == Rc::new(ExprData::NoExprData)))
            && ((n.params.clone().len() as i64) == 0)))
}

